        $folderId=$this->validFolder($folderId,$facilityId);$uuid=$this->uuid();$relative='/media/library/'.date('Y/m');$directory=rtrim($this->publicRoot,'/\\').str_replace('/',DIRECTORY_SEPARATOR,$relative);
