        $tag=(int)($filters['tag']??0);if($tag){$where[]='EXISTS(SELECT 1 FROM media_tag_map mx WHERE mx.media_id=m.id AND mx.tag_id=?)';$params[]=$tag;}
        $facility=(string)($filters['facility']??'all');if($facility==='shared')$where[]='m.facility_id IS NULL';elseif((int)$facility>0){$where[]='m.facility_id=?';$params[]=(int)$facility;}
        $orientation=(string)($filters['orientation']??'all');if($orientation==='landscape')$where[]='m.width>m.height';elseif($orientation==='portrait')$where[]='m.height>m.width';elseif($orientation==='square')$where[]='m.width=m.height AND m.width IS NOT NULL';
        $order=match((string)($filters['sort']??'newest')){'oldest'=>'m.created_at ASC,m.id ASC','name'=>'COALESCE(NULLIF(tr.title,""),m.original_name) ASC,m.id DESC','size'=>'m.size_bytes DESC,m.id DESC',default=>'m.created_at DESC,m.id DESC'};$whereSql=implode(' AND ',$where);
        $count=$this->db->prepare("SELECT COUNT(*) FROM media m WHERE {$whereSql}");$count->execute($params);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);
        $sql="SELECT m.id,m.uuid,m.path url,m.mime_type,m.original_name,m.width,m.height,m.size_bytes,m.status,m.created_at,m.facility_id,m.folder_id,COALESCE(NULLIF(tr.title,''),m.original_name) title,COALESCE(tr.alt_text,'') alt_text,f.name folder_name,COALESCE(ct.name,c.facility_slug,'Shared library') facility_name,COALESCE(u.name,'System') uploaded_by_name,(SELECT v.path FROM media_variants v WHERE v.media_id=m.id ORDER BY FIELD(v.name,'thumb','medium','large'),v.width LIMIT 1) preview_url,(SELECT GROUP_CONCAT(t.name ORDER BY t.name SEPARATOR ', ') FROM media_tag_map mm INNER JOIN media_tags t ON t.id=mm.tag_id WHERE mm.media_id=m.id) tags,(SELECT COUNT(*) FROM pages p WHERE p.featured_media_id=m.id)+(SELECT COUNT(*) FROM posts p WHERE p.featured_media_id=m.id)+(SELECT COUNT(*) FROM post_media pm WHERE pm.media_id=m.id) direct_usage FROM media m LEFT JOIN media_translations tr ON tr.media_id=m.id AND tr.locale=(SELECT locale FROM languages WHERE enabled=1 ORDER BY is_default DESC,sort_order,id LIMIT 1) LEFT JOIN media_folders f ON f.id=m.folder_id LEFT JOIN facilities c ON c.id=m.facility_id LEFT JOIN facility_translations ct ON ct.facility_id=c.id AND ct.locale=(SELECT locale FROM languages WHERE enabled=1 ORDER BY is_default DESC,sort_order,id LIMIT 1) LEFT JOIN users u ON u.id=m.uploaded_by WHERE {$whereSql} ORDER BY {$order} LIMIT ? OFFSET ?";
