    }

    public function folders(?array $facilityIds):array{$scope=$this->scope('f',$facilityIds);$statement=$this->db->prepare('SELECT f.id,f.parent_id,f.facility_id,f.name,f.slug,f.sort_order,COALESCE(ct.name,c.facility_slug,"Shared library") facility_name,(SELECT COUNT(*) FROM media m WHERE m.folder_id=f.id AND m.status="active") media_count FROM media_folders f LEFT JOIN facilities c ON c.id=f.facility_id LEFT JOIN facility_translations ct ON ct.facility_id=c.id AND ct.locale=(SELECT locale FROM languages WHERE enabled=1 ORDER BY is_default DESC,sort_order,id LIMIT 1) WHERE f.archived_at IS NULL AND '.$scope['sql'].' ORDER BY f.facility_id IS NOT NULL,f.sort_order,f.name');$statement->execute($scope['params']);return$statement->fetchAll();}
    public function tags(?array$facilityIds):array{$scope=$this->scope('m',$facilityIds);$statement=$this->db->prepare('SELECT t.id,t.name,t.slug,t.color,COUNT(DISTINCT m.id) media_count FROM media_tags t INNER JOIN media_tag_map mm ON mm.tag_id=t.id INNER JOIN media m ON m.id=mm.media_id AND m.status="active" WHERE '.$scope['sql'].' GROUP BY t.id,t.name,t.slug,t.color ORDER BY t.name');$statement->execute($scope['params']);return$statement->fetchAll();}
    public function saveFolder(array$input,int$userId,bool$canGlobal,?array$facilityIds):array{$id=max(0,(int)($input['id']??0));$facility=max(0,(int)($input['facility_id']??0))?:null;if($facility===null&&!$canGlobal)throw new RuntimeException('You cannot manage shared folders.');if($facility!==null&&$facilityIds!==null&&!in_array($facility,$facilityIds,true))throw new RuntimeException('You do not have access to the selected facility.');$name=mb_substr(trim((string)($input['name']??'')),0,120);if(mb_strlen($name)<2)throw new RuntimeException('Folder name must contain at least two characters.');$parent=max(0,(int)($input['parent_id']??0))?:null;if($parent===$id)throw new RuntimeException('A folder cannot contain itself.');$parent=$this->validFolder($parent,$facility);if($id){$current=$this->folder($id);if(!$current)throw new RuntimeException('The folder was not found.');$this->assertWritableScope($current,$canGlobal,$facilityIds);if((int)($current['facility_id']??0)!==(int)$facility)throw new RuntimeException('Move media out of the folder before changing its facility.');if($this->isFolderDescendant($parent,$id))throw new RuntimeException('The selected parent would create a folder cycle.');$this->db->prepare('UPDATE media_folders SET parent_id=?,name=?,slug=?,updated_at=NOW() WHERE id=?')->execute([$parent,$name,$this->uniqueFolderSlug($name,$facility,$id),$id]);}else{$this->db->prepare('INSERT INTO media_folders (parent_id,facility_id,name,slug,sort_order,created_by,created_at,updated_at) VALUES (?,?,?,?,0,?,NOW(),NOW())')->execute([$parent,$facility,$name,$this->uniqueFolderSlug($name,$facility),$userId]);$id=(int)$this->db->lastInsertId();}$this->audit($userId,'media.folder.saved',$id,['facility_id'=>$facility],'media_folder');return$this->folder($id)??[];}
