    public function emptyTrash(int$userId,bool$canGlobal,?array$facilityIds):array{$scope=$this->scope('m',$facilityIds);$statement=$this->db->prepare('SELECT m.id FROM media m WHERE m.status="trash" AND '.$scope['sql'].' ORDER BY m.id');$statement->execute($scope['params']);$ids=array_map('intval',$statement->fetchAll(PDO::FETCH_COLUMN));$deleted=0;$blocked=0;foreach($ids as$id){try{$this->destroy($id,$userId,$canGlobal,$facilityIds);$deleted++;}catch(RuntimeException){$blocked++;}}return['deleted'=>$deleted,'blocked'=>$blocked];}

